#!/usr/bin/env python3
# Annuaire : cartouches typographiques pour les maisons sans logo
# Remplace les zones vides et les images inaccessibles par le nom de la maison.
from pathlib import Path
import hashlib
import json
ENTRIES = json.loads('[{"path": "annuaire.html", "old_sha256": "3fa760d1988d9f33b3d66b839596dca898ae397dfcdd122c2af3102a7c9170a9", "new_sha256": "09638e799bdcf6d9d63b64a6975028154eaf647663f0861df3bbe7aa4c12bcae", "prefix": 1239, "suffix": 262154, "replacement": "27-cartouches\\">\\n  <script src=\\"/assets/ecosysteme/maison/app.js?v=20260927-cartouches"}, {"path": "assets/ecosysteme/maison/app.js", "old_sha256": "87c5bbea0f94077cbe07689392795c4678f19053b1af35987ad08bb342fa3776", "new_sha256": "2b6566d8da7503c906d130255e520d6e658b1c84e14038a3761ba512b98c4c17", "prefix": 1458, "suffix": 4878, "replacement": "showHouseName(mark, name) {\\n  mark.classList.remove(\'logo-dark\', \'logo-wide\');\\n  mark.classList.add(\'logo-unavailable\');\\n  mark.classList.toggle(\'logo-name-long\', name.length > 24);\\n  mark.replaceChildren(el(\'span\', \'house-nameplate\', name));\\n}\\nfunction closeCategories() {\\n  categoryList.classList.remove(\'open\');\\n  toggle.setAttribute(\'aria-expanded\', \'false\');\\n  toggle.lastElementChild.textContent = \'+\';\\n}\\nfunction updateURL() {\\n  const params = new URLSearchParams();\\n  if (input.value.trim()) params.set(\'q\', input.value.trim());\\n  if (active) params.set(\'metier\', active);\\n  const query = params.toString();\\n  history.replaceState(null, \'\', location.pathname + (query ? \'?\' + query : \'\') + location.hash);\\n}\\nfunction renderCategories() {\\n  categoryList.replaceChildren();\\n  const choices = [{ id: \'\', name: \'Toutes les maisons\' }, ...categories];\\n  choices.forEach((category) => {\\n    const button = el(\'button\', \'category-button\');\\n    button.type = \'button\';\\n    button.dataset.category = category.id;\\n    button.setAttribute(\'aria-pressed\', String(active === category.id));\\n    const count = category.id ? houses.filter(h => h.categories.includes(category.id)).length : houses.length;\\n    button.append(el(\'span\', \'\', labels[category.id] || category.name), el(\'span\', \'\', number.format(count)));\\n    button.addEventListener(\'click\', () => {\\n      active = category.id; limit = pageSize; closeCategories(); render();\\n      if (matchMedia(\'(max-width:800px)\').matches) $(\'#results-title\').focus({ preventScroll: true });\\n    });\\n    categoryList.append(button);\\n  });\\n}\\nfunction render() {\\n  const words = normalize(input.value).split(\' \').filter(Boolean);\\n  const filtered = houses.filter(h => (!active || h.categories.includes(active)) && words.every(w => h.search.includes(w)));\\n  const previousSize = results.children.length;\\n  const visible = filtered.slice(0, limit);\\n  results.replaceChildren();\\n  visible.forEach(h => {\\n    const item = el(\'article\', \'house\');\\n    const a = el(\'a\');\\n    a.href = `/f/${encodeURIComponent(h.slug)}`;\\n    const top = el(\'div\', \'house-top\');\\n    const mark = el(\'span\', \'house-mark\');\\n    mark.setAttribute(\'aria-hidden\', \'true\');\\n    if (h.logo) {\\n      const img = document.createElement(\'img\');\\n      img.src = h.logo.src || `assets/${h.slug}.webp`; img.alt = \'\'; img.loading = \'lazy\'; img.decoding = \'async\';\\n      if (h.logo.dark) mark.classList.add(\'logo-dark\');\\n      if (h.logo.wide) mark.classList.add(\'logo-wide\');\\n      img.addEventListener(\'error\', () => showHouseName(mark, h.name), { once: true });\\n      mark.append(img);\\n    } else { showHouseName(mark, h.name"}, {"path": "assets/ecosysteme/maison/style.css", "old_sha256": "6e4503a2fe04e7a5e89eae770e06016943f52ad5d407269a78daa6320e8c960a", "new_sha256": "bf3d2cc6e229199c07706554f17c2948cddd785ba2a617e98bad3fd6767a4035", "prefix": 14832, "suffix": 0, "replacement": "\\n/* A neutral nameplate fills missing logos without inventing a brand identity. */\\n.house-mark.logo-unavailable{height:auto;min-height:52px;padding:10px 12px;border:1px solid var(--line);background:var(--wash);color:var(--ink);justify-content:center}\\n.house-nameplate{font:500 12px/1.3 var(--sans);letter-spacing:.045em;text-transform:uppercase;text-align:center;overflow-wrap:anywhere;text-wrap:balance;min-width:0}\\n.house-mark.logo-name-long{width:180px}\\n.logo-name-long .house-nameplate{font-size:11px;letter-spacing:.025em}\\n@media(max-width:560px){.house-mark.logo-unavailable{min-height:46px;padding:8px}.house-nameplate{font-size:11px}.logo-name-long .house-nameplate{font-size:10px}}\\n"}]')
changes = []
for entry in ENTRIES:
    path = Path(entry['path'])
    original = path.read_bytes()
    if hashlib.sha256(original).hexdigest() != entry['old_sha256']:
        raise SystemExit('Fichier modifie depuis la preparation : ' + str(path))
    text = original.decode('utf-8')
    suffix = text[len(text)-entry['suffix']:] if entry['suffix'] else ''
    result = (text[:entry['prefix']] + entry['replacement'] + suffix).encode('utf-8')
    assert hashlib.sha256(result).hexdigest() == entry['new_sha256'], str(path)
    changes.append((path,result))
for path, result in changes:
    path.write_bytes(result)
    print('Mis a jour :', path)
